-- MarketingHub AI · Esquema para Supabase externo
-- Pegar en SQL Editor del proyecto. Idempotente.
-- AVISO: sin autenticación aún, las políticas permiten leer/escribir con la publishable key (solo demo).

create table if not exists public.clientes (id text primary key, segmento text, datos jsonb not null, actualizado timestamptz default now());
create table if not exists public.productos (id text primary key, nombre text, datos jsonb not null, actualizado timestamptz default now());
create table if not exists public.campanas (id text primary key, estado text, producto_id text, datos jsonb not null, actualizado timestamptz default now());
create table if not exists public.mensajes (id text primary key, campana_id text, cliente_id text, estado text, riesgo_legal text, datos jsonb not null, actualizado timestamptz default now());
create table if not exists public.auditoria_legal (id bigserial primary key, entidad text not null, entidad_id text not null, accion text not null, usuario text, detalle jsonb, fecha timestamptz default now());
create index if not exists mensajes_campana_idx on public.mensajes(campana_id);

do $$ declare t text; begin
  foreach t in array array['clientes','productos','campanas','mensajes','auditoria_legal'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('grant select, insert, update on public.%I to anon, authenticated', t);
    execute format('drop policy if exists demo_rw_sel on public.%I', t);
    execute format('drop policy if exists demo_rw_ins on public.%I', t);
    execute format('drop policy if exists demo_rw_upd on public.%I', t);
    execute format('create policy demo_rw_sel on public.%I for select to anon, authenticated using (true)', t);
    execute format('create policy demo_rw_ins on public.%I for insert to anon, authenticated with check (true)', t);
    execute format('create policy demo_rw_upd on public.%I for update to anon, authenticated using (true) with check (true)', t);
  end loop; end $$;
grant usage, select on sequence public.auditoria_legal_id_seq to anon, authenticated;

